import{_ as d,o as r,c as e,a3 as a}from"./chunks/framework.Ba39LDvt.js";const S=JSON.parse('{"title":"常用术语表","description":"按器件、数字设计、实现验证、模拟、系统与产业整理常见 IC 英文缩写。","frontmatter":{"title":"常用术语表","description":"按器件、数字设计、实现验证、模拟、系统与产业整理常见 IC 英文缩写。"},"headers":[],"relativePath":"basics/glossary.md","filePath":"basics/glossary.md","lastUpdated":1795513256000}'),i={name:"basics/glossary.md"};function o(n,t,s,h,l,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="常用术语表" tabindex="-1">常用术语表 <a class="header-anchor" href="#常用术语表" aria-label="Permalink to &quot;常用术语表&quot;">​</a></h1><p>查术语时，先看它属于哪个抽象层。同一个缩写在不同领域可能有不同含义；本页采用芯片学习中常见的用法，不替代课程中的严格定义。理解流程可看 <a href="/shanghaitech-ic-wiki-dev.github.io/basics/design-flow">芯片设计全流程</a>，遇到课程代码则查 <a href="/shanghaitech-ic-wiki-dev.github.io/courses/">课程总览</a>。</p><h2 id="器件、材料与工艺" tabindex="-1">器件、材料与工艺 <a class="header-anchor" href="#器件、材料与工艺" aria-label="Permalink to &quot;器件、材料与工艺&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>英文全称</th><th>中文</th><th>一句话解释</th></tr></thead><tbody><tr><td>IC</td><td>Integrated Circuit</td><td>集成电路</td><td>将器件和互连集成在半导体等基底上形成的电路。</td></tr><tr><td>MOSFET</td><td>Metal-Oxide-Semiconductor Field-Effect Transistor</td><td>金属氧化物半导体场效应晶体管</td><td>通过栅极电场调节沟道电流的晶体管。</td></tr><tr><td>CMOS</td><td>Complementary Metal-Oxide-Semiconductor</td><td>互补金属氧化物半导体</td><td>使用互补型 MOS 器件实现电路的技术。</td></tr><tr><td>NMOS</td><td>N-Channel MOS</td><td>N 沟道 MOS</td><td>以电子作为沟道主要载流子的 MOS 器件。</td></tr><tr><td>PMOS</td><td>P-Channel MOS</td><td>P 沟道 MOS</td><td>以空穴作为沟道主要载流子的 MOS 器件。</td></tr><tr><td>BJT</td><td>Bipolar Junction Transistor</td><td>双极结型晶体管</td><td>依靠双极载流子输运工作的晶体管。</td></tr><tr><td>FinFET</td><td>Fin Field-Effect Transistor</td><td>鳍式场效应晶体管</td><td>使用鳍形沟道增强栅极控制的器件。</td></tr><tr><td>GAA</td><td>Gate-All-Around</td><td>环栅结构</td><td>栅极环绕沟道以增强静电控制的结构。</td></tr><tr><td>CFET</td><td>Complementary Field-Effect Transistor</td><td>互补场效应晶体管</td><td>常指将互补型器件垂直集成的结构路线。</td></tr><tr><td>SOI</td><td>Silicon on Insulator</td><td>绝缘体上硅</td><td>在绝缘层上形成硅器件层的材料结构。</td></tr><tr><td>GaN</td><td>Gallium Nitride</td><td>氮化镓</td><td>可用于功率与高频器件的宽禁带半导体。</td></tr><tr><td>SiC</td><td>Silicon Carbide</td><td>碳化硅</td><td>可用于高压功率器件等领域的宽禁带半导体。</td></tr><tr><td>SCE</td><td>Short-Channel Effects</td><td>短沟道效应</td><td>沟道缩短后出现的一组偏离长沟道行为的效应。</td></tr><tr><td>DIBL</td><td>Drain-Induced Barrier Lowering</td><td>漏致势垒降低</td><td>漏极电压影响源端势垒而改变器件行为的效应。</td></tr><tr><td>CVD</td><td>Chemical Vapor Deposition</td><td>化学气相沉积</td><td>通过气相化学反应在表面形成薄膜的工艺。</td></tr><tr><td>ALD</td><td>Atomic Layer Deposition</td><td>原子层沉积</td><td>通过自限制表面反应逐层形成薄膜的工艺。</td></tr><tr><td>CMP</td><td>Chemical Mechanical Polishing</td><td>化学机械抛光</td><td>综合化学与机械作用实现表面平坦化的工艺。</td></tr><tr><td>EUV</td><td>Extreme Ultraviolet</td><td>极紫外</td><td>在先进光刻中使用的短波长光技术类别。</td></tr><tr><td>BEOL</td><td>Back End of Line</td><td>后道互连工艺</td><td>器件形成后构建互连等结构的制造阶段。</td></tr><tr><td>FEOL</td><td>Front End of Line</td><td>前道器件工艺</td><td>在晶圆上形成晶体管等器件的制造阶段。</td></tr></tbody></table><h2 id="数字设计与验证" tabindex="-1">数字设计与验证 <a class="header-anchor" href="#数字设计与验证" aria-label="Permalink to &quot;数字设计与验证&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>英文全称</th><th>中文</th><th>一句话解释</th></tr></thead><tbody><tr><td>RTL</td><td>Register-Transfer Level</td><td>寄存器传输级</td><td>用寄存器状态及其间数据转换描述同步硬件的抽象层。</td></tr><tr><td>HDL</td><td>Hardware Description Language</td><td>硬件描述语言</td><td>用于描述硬件结构与行为的语言。</td></tr><tr><td>SV</td><td>SystemVerilog</td><td>SystemVerilog 语言</td><td>扩展 Verilog、支持设计与验证的标准语言。</td></tr><tr><td>FSM</td><td>Finite-State Machine</td><td>有限状态机</td><td>用有限状态和转移规则描述控制行为的模型。</td></tr><tr><td>FF</td><td>Flip-Flop</td><td>触发器</td><td>按时钟事件保存状态的时序元件。</td></tr><tr><td>CDC</td><td>Clock Domain Crossing</td><td>跨时钟域</td><td>信号在不同时钟域之间传递的问题。</td></tr><tr><td>RDC</td><td>Reset Domain Crossing</td><td>跨复位域</td><td>不同复位关系之间信号交互的问题。</td></tr><tr><td>UVM</td><td>Universal Verification Methodology</td><td>通用验证方法学</td><td>基于 SystemVerilog 的可复用验证方法与类库体系。</td></tr><tr><td>SVA</td><td>SystemVerilog Assertions</td><td>SystemVerilog 断言</td><td>描述并检查设计性质和时序关系的语言机制。</td></tr><tr><td>BMC</td><td>Bounded Model Checking</td><td>有界模型检查</td><td>在有限展开深度内寻找性质反例的形式方法。</td></tr><tr><td>DFT</td><td>Design for Testability</td><td>可测性设计</td><td>在设计中加入结构以提高制造后测试能力。</td></tr><tr><td>ATPG</td><td>Automatic Test Pattern Generation</td><td>自动测试向量生成</td><td>针对故障模型自动生成测试激励。</td></tr><tr><td>BIST</td><td>Built-In Self-Test</td><td>内建自测试</td><td>由芯片内部逻辑生成或检查测试的技术。</td></tr><tr><td>MBIST</td><td>Memory Built-In Self-Test</td><td>存储器内建自测试</td><td>面向片上存储器的内建测试技术。</td></tr><tr><td>ECO</td><td>Engineering Change Order</td><td>工程变更</td><td>在已有实现上进行受控修改以修复或优化设计。</td></tr></tbody></table><h2 id="综合、物理实现与签核" tabindex="-1">综合、物理实现与签核 <a class="header-anchor" href="#综合、物理实现与签核" aria-label="Permalink to &quot;综合、物理实现与签核&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>英文全称</th><th>中文</th><th>一句话解释</th></tr></thead><tbody><tr><td>EDA</td><td>Electronic Design Automation</td><td>电子设计自动化</td><td>支持电路设计、验证与实现的软件方法体系。</td></tr><tr><td>PDK</td><td>Process Design Kit</td><td>工艺设计套件</td><td>将某项制造工艺的模型和规则提供给设计端的数据集合。</td></tr><tr><td>PPA</td><td>Power, Performance, Area</td><td>功耗、性能、面积</td><td>评价设计取舍的一组常用指标。</td></tr><tr><td>P&amp;R</td><td>Placement and Routing</td><td>布局布线</td><td>决定单元位置并完成物理连线的过程。</td></tr><tr><td>CTS</td><td>Clock Tree Synthesis</td><td>时钟树综合</td><td>构造时钟分配网络并控制其延迟与偏斜。</td></tr><tr><td>STA</td><td>Static Timing Analysis</td><td>静态时序分析</td><td>基于时序图和约束检查路径时序的方法。</td></tr><tr><td>SDC</td><td>Synopsys Design Constraints</td><td>设计约束格式</td><td>描述时钟和时序例外等约束的常用命令格式。</td></tr><tr><td>SDF</td><td>Standard Delay Format</td><td>标准延迟格式</td><td>交换并回标单元或互连延迟等信息的格式。</td></tr><tr><td>SPEF</td><td>Standard Parasitic Exchange Format</td><td>标准寄生交换格式</td><td>表达互连寄生电阻电容等参数的格式。</td></tr><tr><td>LEF</td><td>Library Exchange Format</td><td>库交换格式</td><td>描述工艺层及单元抽象物理信息的格式。</td></tr><tr><td>DEF</td><td>Design Exchange Format</td><td>设计交换格式</td><td>交换布局布线等设计物理信息的格式。</td></tr><tr><td>GDSII</td><td>Graphic Data System II</td><td>版图数据格式</td><td>交付和交换版图几何图形的常用格式。</td></tr><tr><td>DRC</td><td>Design Rule Check</td><td>设计规则检查</td><td>检查版图几何是否符合工艺规则。</td></tr><tr><td>LVS</td><td>Layout Versus Schematic</td><td>版图原理图一致性检查</td><td>比较版图提取电路与原理图或网表的连接关系。</td></tr><tr><td>PEX</td><td>Parasitic Extraction</td><td>寄生参数提取</td><td>从物理版图估计互连等产生的寄生参数。</td></tr><tr><td>PVT</td><td>Process, Voltage, Temperature</td><td>工艺、电压、温度</td><td>描述设计分析条件的主要维度。</td></tr><tr><td>OCV</td><td>On-Chip Variation</td><td>片上变异</td><td>同一芯片不同位置器件与路径参数的变化。</td></tr><tr><td>EM</td><td>Electromigration</td><td>电迁移</td><td>电流作用下金属原子迁移引起的可靠性问题。</td></tr><tr><td>SI</td><td>Signal Integrity</td><td>信号完整性</td><td>研究耦合、反射等因素对信号质量的影响。</td></tr></tbody></table><h2 id="模拟、射频与测量" tabindex="-1">模拟、射频与测量 <a class="header-anchor" href="#模拟、射频与测量" aria-label="Permalink to &quot;模拟、射频与测量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>英文全称</th><th>中文</th><th>一句话解释</th></tr></thead><tbody><tr><td>ADC</td><td>Analog-to-Digital Converter</td><td>模数转换器</td><td>将连续模拟信号转换成数字表示的电路。</td></tr><tr><td>DAC</td><td>Digital-to-Analog Converter</td><td>数模转换器</td><td>将数字码转换成模拟输出的电路。</td></tr><tr><td>PLL</td><td>Phase-Locked Loop</td><td>锁相环</td><td>利用反馈使输出相位或频率跟踪参考的系统。</td></tr><tr><td>LDO</td><td>Low-Dropout Regulator</td><td>低压差线性稳压器</td><td>在较小输入输出压差下工作的线性稳压电路。</td></tr><tr><td>LNA</td><td>Low-Noise Amplifier</td><td>低噪声放大器</td><td>用于接收链路前端并尽量少引入噪声的放大器。</td></tr><tr><td>PA</td><td>Power Amplifier</td><td>功率放大器</td><td>为负载或天线提供较大信号功率的电路。</td></tr><tr><td>SNR</td><td>Signal-to-Noise Ratio</td><td>信噪比</td><td>信号功率与噪声功率之比。</td></tr><tr><td>ENOB</td><td>Effective Number of Bits</td><td>有效位数</td><td>将转换器实际性能折算为理想量化位数的指标。</td></tr><tr><td>CMRR</td><td>Common-Mode Rejection Ratio</td><td>共模抑制比</td><td>衡量电路抑制共模输入能力的指标。</td></tr><tr><td>PSRR</td><td>Power Supply Rejection Ratio</td><td>电源抑制比</td><td>衡量电源变化耦合到输出程度的指标。</td></tr><tr><td>GBW</td><td>Gain-Bandwidth Product</td><td>增益带宽积</td><td>在适用模型下刻画放大器增益与带宽关系的指标。</td></tr><tr><td>ATE</td><td>Automatic Test Equipment</td><td>自动测试设备</td><td>对芯片施加激励并自动采集判定结果的设备。</td></tr></tbody></table><h2 id="系统、存储与产业" tabindex="-1">系统、存储与产业 <a class="header-anchor" href="#系统、存储与产业" aria-label="Permalink to &quot;系统、存储与产业&quot;">​</a></h2><table tabindex="0"><thead><tr><th>缩写</th><th>英文全称</th><th>中文</th><th>一句话解释</th></tr></thead><tbody><tr><td>SoC</td><td>System on Chip</td><td>片上系统</td><td>集成计算、存储、互连与接口等功能的芯片系统。</td></tr><tr><td>ISA</td><td>Instruction Set Architecture</td><td>指令集架构</td><td>定义机器指令及软件可见行为的接口规范。</td></tr><tr><td>CPU</td><td>Central Processing Unit</td><td>中央处理器</td><td>执行通用指令流的计算单元。</td></tr><tr><td>GPU</td><td>Graphics Processing Unit</td><td>图形处理器</td><td>适合大规模并行工作负载的处理器类别。</td></tr><tr><td>NPU</td><td>Neural Processing Unit</td><td>神经网络处理器</td><td>面向神经网络运算优化的处理单元类别。</td></tr><tr><td>FPGA</td><td>Field-Programmable Gate Array</td><td>现场可编程门阵列</td><td>制造后仍可配置逻辑与互连的可编程芯片。</td></tr><tr><td>ASIC</td><td>Application-Specific Integrated Circuit</td><td>专用集成电路</td><td>面向特定应用设计的集成电路。</td></tr><tr><td>SRAM</td><td>Static Random-Access Memory</td><td>静态随机存储器</td><td>依靠双稳态电路保存数据、上电时无需刷新的一类存储器。</td></tr><tr><td>DRAM</td><td>Dynamic Random-Access Memory</td><td>动态随机存储器</td><td>依靠电荷存储并需要周期刷新的存储器。</td></tr><tr><td>HBM</td><td>High Bandwidth Memory</td><td>高带宽存储器</td><td>采用堆叠与宽接口提供高带宽的存储技术。</td></tr><tr><td>MRAM</td><td>Magnetoresistive Random-Access Memory</td><td>磁性随机存储器</td><td>利用磁性状态及磁阻效应读写信息的存储器。</td></tr><tr><td>CIM</td><td>Compute-in-Memory</td><td>存内计算</td><td>在存储阵列内或紧邻阵列完成部分计算的技术。</td></tr><tr><td>NoC</td><td>Network on Chip</td><td>片上网络</td><td>连接片上模块并传输数据的网络化互连。</td></tr><tr><td>CPO</td><td>Co-Packaged Optics</td><td>光电共封装</td><td>将光学引擎与电子芯片在封装层面紧密集成。</td></tr><tr><td>TSV</td><td>Through-Silicon Via</td><td>硅通孔</td><td>穿过硅基底以实现垂直电连接的结构。</td></tr><tr><td>IP</td><td>Intellectual Property</td><td>知识产权核</td><td>在芯片语境中常指可授权复用的设计模块。</td></tr><tr><td>IDM</td><td>Integrated Device Manufacturer</td><td>垂直整合制造商</td><td>同时具有芯片设计与制造等业务的企业。</td></tr><tr><td>OSAT</td><td>Outsourced Semiconductor Assembly and Test</td><td>外包半导体封装测试</td><td>向其他芯片企业提供封装与测试服务的业务类别。</td></tr><tr><td>MPW</td><td>Multi-Project Wafer</td><td>多项目晶圆</td><td>多个设计共享同批晶圆制造资源的服务方式。</td></tr><tr><td>NRE</td><td>Non-Recurring Engineering</td><td>非重复性工程费用</td><td>项目中不随每颗芯片重复发生的研发等费用。</td></tr></tbody></table><h2 id="使用提醒" tabindex="-1">使用提醒 <a class="header-anchor" href="#使用提醒" aria-label="Permalink to &quot;使用提醒&quot;">​</a></h2><p>同一页报告里，<code>SI</code> 也可能表示国际单位制，<code>IP</code> 也可能指网络协议。缩写必须服从上下文。PPA、良率、吞吐、能效等指标还需要说明测量范围与条件：芯片核心、整个裸片、开发板和整机的结果不能直接混用。</p>',14)])])}const g=d(i,[["render",o]]);export{S as __pageData,g as default};
